void custom_log(FILE *stream, const char *fmt, ...) {
    va_list args;
    int chars_printed;

    va_start(args, fmt);

    // vfprintf performs the actual writing and formatting
    chars_printed = vfprintf(stream, fmt, args);

    va_end(args);
    // Use chars_printed for error handling if needed
}

